const html = String($input.first().json.data ?? $input.first().json.body ?? '');
function match(re){ const m = html.match(re); return m ? m[1].trim() : ''; }
const title = match(/<title[^>]*>([^<]+)<\/title>/i);
const ogSite = match(/<meta[^>]+property=["']og:site_name["'][^>]+content=["']([^"']+)["']/i);
const metaDesc = match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i);
const ogDesc = match(/<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']+)["']/i);
const firstP = match(/<p[^>]*>([^<]+)<\/p>/i);
const h2s = [...html.matchAll(/<h2[^>]*>([^<]+)<\/h2>/gi)].map(m=>m[1].trim()).slice(0,5);
const summary = metaDesc || ogDesc || firstP.slice(0,300);
const hay = (summary + ' ' + title).toLowerCase();
const KW = [['saas','SaaS'],['e-commerce','E-commerce'],['ecommerce','E-commerce'],['fintech','FinTech'],['healthcare','Healthcare'],['consulting','Consulting'],['marketing','Marketing'],['logistics','Logistics'],['manufacturing','Manufacturing'],['ai','AI / ML']];
let industry = '';
for (const [n,l] of KW) if (hay.includes(n)) { industry = l; break; }
return [{ json: { company_name: ogSite || title || '', summary, industry, services: h2s } }];
